"""Render a RedTeamReport as Markdown, standalone HTML, or JSON."""
from __future__ import annotations

import html
import json
from collections import defaultdict

from .schemas import RedTeamReport, ReportFinding

DECISION_LABEL = {"GO": "GO", "GO_WITH_CONDITIONS": "GO WITH CONDITIONS", "NO_GO": "NO-GO"}
SEV_ICON = {"blocker": "🛑", "high": "🔴", "medium": "🟠", "low": "🟡"}
GO_NOTE = "No blockers found. This is not an approval: human sign-off is still required."
DISCLAIMER = (
    "Generated by an AI red-team agent. Treat findings as a structured starting point for human review. "
    "Regulatory references are leads to verify with counsel, not legal advice."
)


# ------------------------------------------------------------------ markdown
def to_markdown(r: RedTeamReport) -> str:
    out: list[str] = []
    v = r.verdict
    c = r.counts()
    out.append(f"# PRD Red-Team Review: {r.prd_title}\n")
    out.append(f"_Generated {r.generated_at} · model `{r.model}` · {len(r.personas_run)} reviewers_\n")
    if v:
        out.append(f"## Verdict: **{DECISION_LABEL[v.decision]}**\n")
        if r.gate_override:
            out.append(f"> ⚖️ {r.gate_override}\n")
        if v.decision == "GO":
            out.append(f"> {GO_NOTE}\n")
        out.append(v.executive_summary + "\n")
        out.append(
            f"**Findings:** {c['blocker']} blocker · {c['high']} high · {c['medium']} medium · {c['low']} low "
            f"· plus {len(r.lint_findings)} hygiene issues\n"
        )
        if v.launch_conditions:
            out.append("### Launch conditions\n")
            out += [f"- [ ] {cond}" for cond in v.launch_conditions]
            out.append("")
        if v.scorecard:
            out.append("### Scorecard\n")
            out.append("| Dimension | Score | Note |\n|---|---|---|")
            out += [f"| {s.dimension} | {'●' * s.score}{'○' * (5 - s.score)} {s.score}/5 | {s.note} |" for s in v.scorecard]
            out.append("")
        top = [f for f in r.findings + r.lint_findings if f.id in set(v.top_risk_ids)]
        if top:
            out.append("### Top risks\n")
            out += [f"1. **{f.id}** {SEV_ICON[f.severity]} {f.title}" for f in top]
            out.append("")

    if r.persona_takes:
        out.append("## The panel\n")
        out.append("| Reviewer | Signs off? | Take |\n|---|---|---|")
        for name, take in r.persona_takes.items():
            out.append(f"| {name} | {'✅' if r.persona_signoffs.get(name) else '❌'} | {take} |")
        out.append("")

    if r.findings:
        out.append("## Findings\n")
        for sev in ("blocker", "high", "medium", "low"):
            group = [f for f in r.findings if f.severity == sev]
            if not group:
                continue
            out.append(f"### {SEV_ICON[sev]} {sev.title()} ({len(group)})\n")
            for f in group:
                out.append(_finding_md(f))

    if r.findings:
        out.append("## Questions to answer before the review meeting\n")
        by_persona: dict[str, list[ReportFinding]] = defaultdict(list)
        for f in r.findings:
            by_persona[f.personas[0]].append(f)
        for persona, fs in by_persona.items():
            out.append(f"**{persona}**")
            out += [f"- ({f.id}) {f.question_for_pm}" for f in fs]
            out.append("")

    if r.lint_findings:
        out.append("## PRD hygiene checks\n")
        out.append("| ID | Severity | Issue | Where |\n|---|---|---|---|")
        for f in r.lint_findings:
            where = f"L{f.line}" if f.line else f.section
            out.append(f"| {f.id} | {f.severity} | {f.title}. {f.issue} | {where} |")
        out.append("")

    if r.stats:
        out.append("<details><summary>Run stats</summary>\n")
        out += [f"- {k}: {val}" for k, val in r.stats.items()]
        out.append("\n</details>\n")
    out.append(f"---\n_{DISCLAIMER}_\n")
    return "\n".join(out)


def _finding_md(f: ReportFinding) -> str:
    loc = f"L{f.line}" if f.line else ""
    verified = {True: "✓ quote verified", False: "⚠ quote not found in PRD", None: "omission"}[f.evidence_verified]
    lines = [
        f"#### {f.id} · {f.title}",
        f"`{f.category}` · **{', '.join(f.personas)}** · section: _{f.section}_ {loc} · confidence {f.confidence:.0%} · {verified}\n",
    ]
    if f.evidence:
        lines.append(f"> {f.evidence}\n")
    lines += [
        f"**Issue.** {f.issue}\n",
        f"**What goes wrong.** {f.failure_scenario}\n",
        f"**Fix.** {f.recommendation}\n",
    ]
    if f.moderator_note:
        lines.append(f"_Moderator: {f.moderator_note}_\n")
    return "\n".join(lines)


# ------------------------------------------------------------------ html
_CSS = """
:root{--bg:#fafaf7;--card:#fff;--ink:#1d1d1b;--mute:#6b6b66;--line:#e6e4dc;
--blocker:#9b1c1c;--high:#d14343;--medium:#d9822b;--low:#b8a200;--go:#1f7a4d;--cond:#b26b00;--nogo:#9b1c1c}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 -apple-system,Segoe UI,Inter,Roboto,sans-serif}
main{max-width:980px;margin:0 auto;padding:40px 24px 80px}h1{font-size:28px;margin:0 0 4px}h2{margin-top:40px;font-size:20px}
.meta{color:var(--mute);font-size:13px}.verdict{display:flex;gap:20px;align-items:center;background:var(--card);border:1px solid var(--line);
border-radius:14px;padding:20px 24px;margin:24px 0}.badge{font-weight:800;letter-spacing:.04em;padding:10px 16px;border-radius:10px;color:#fff;white-space:nowrap}
.GO{background:var(--go)}.GO_WITH_CONDITIONS{background:var(--cond)}.NO_GO{background:var(--nogo)}
.counts{display:flex;gap:10px;flex-wrap:wrap;margin:8px 0 0}.pill{border-radius:999px;padding:2px 10px;font-size:12px;font-weight:600;color:#fff}
.blocker{background:var(--blocker)}.high{background:var(--high)}.medium{background:var(--medium)}.low{background:var(--low)}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 20px;margin:12px 0}
.card h4{margin:0 0 6px;font-size:16px}.tags{font-size:12px;color:var(--mute);margin-bottom:8px}
blockquote{margin:8px 0;padding:6px 12px;border-left:3px solid var(--line);color:#444;background:#f6f5f0;border-radius:4px}
table{width:100%;border-collapse:collapse;background:var(--card);border:1px solid var(--line);border-radius:12px;overflow:hidden}
td,th{padding:8px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;font-size:14px}th{background:#f3f2ec}
.bar{display:inline-block;height:8px;border-radius:4px;background:var(--line);width:100px;vertical-align:middle;margin-right:8px}
.bar>i{display:block;height:8px;border-radius:4px;background:var(--ink)}.override{color:var(--nogo);font-weight:600}
.filters{display:flex;gap:8px;margin:8px 0 4px}.filters button{border:1px solid var(--line);background:var(--card);border-radius:8px;padding:4px 10px;cursor:pointer}
.filters button.on{background:var(--ink);color:#fff}footer{margin-top:40px;color:var(--mute);font-size:12px}
ul.cond{padding-left:20px}ul.cond li{margin:4px 0}
"""

_JS = """
document.querySelectorAll('.filters button').forEach(b=>b.onclick=()=>{
 document.querySelectorAll('.filters button').forEach(x=>x.classList.remove('on'));b.classList.add('on');
 const s=b.dataset.sev;document.querySelectorAll('.finding').forEach(c=>c.style.display=(s==='all'||c.dataset.sev===s)?'':'none');});
"""


def to_html(r: RedTeamReport) -> str:
    e = html.escape
    v = r.verdict
    c = r.counts()
    parts = [f"<!DOCTYPE html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
             f"<title>Red-team: {e(r.prd_title)}</title><style>{_CSS}</style></head><body><main>"]
    parts.append(f"<h1>PRD Red-Team Review: {e(r.prd_title)}</h1>"
                 f"<div class='meta'>Generated {e(r.generated_at)} · model {e(r.model)} · {len(r.personas_run)} reviewers</div>")
    if v:
        pills = "".join(f"<span class='pill {s}'>{c[s]} {s}</span>" for s in ("blocker", "high", "medium", "low"))
        override = f"<p class='override'>{e(r.gate_override)}</p>" if r.gate_override else ""
        if v.decision == "GO":
            override += f"<p class='meta'>{e(GO_NOTE)}</p>"
        parts.append(f"<section class='verdict'><div class='badge {v.decision}'>{DECISION_LABEL[v.decision]}</div>"
                     f"<div><div>{e(v.executive_summary)}</div><div class='counts'>{pills}"
                     f"<span class='pill' style='background:#888'>{len(r.lint_findings)} hygiene</span></div>{override}</div></section>")
        if v.launch_conditions:
            parts.append("<h2>Launch conditions</h2><ul class='cond'>" + "".join(f"<li>☐ {e(x)}</li>" for x in v.launch_conditions) + "</ul>")
        if v.scorecard:
            rows = "".join(f"<tr><td>{e(s.dimension)}</td><td><span class='bar'><i style='width:{s.score * 20}%'></i></span>{s.score}/5</td><td>{e(s.note)}</td></tr>"
                           for s in v.scorecard)
            parts.append(f"<h2>Scorecard</h2><table><tr><th>Dimension</th><th>Score</th><th>Note</th></tr>{rows}</table>")
    if r.persona_takes:
        rows = "".join(f"<tr><td><b>{e(n)}</b></td><td>{'✅' if r.persona_signoffs.get(n) else '❌'}</td><td>{e(t)}</td></tr>"
                       for n, t in r.persona_takes.items())
        parts.append(f"<h2>The panel</h2><table><tr><th>Reviewer</th><th>Signs off</th><th>Take</th></tr>{rows}</table>")
    if r.findings:
        parts.append("<h2>Findings</h2><div class='filters'>" + "".join(
            f"<button data-sev='{s}' class='{'on' if s == 'all' else ''}'>{s}</button>" for s in ("all", "blocker", "high", "medium", "low")) + "</div>")
        for f in r.findings:
            parts.append(_finding_html(f))
    if r.lint_findings:
        rows = "".join(f"<tr><td>{f.id}</td><td><span class='pill {f.severity}'>{f.severity}</span></td><td><b>{e(f.title)}</b><br>{e(f.issue)}</td>"
                       f"<td>{('L' + str(f.line)) if f.line else e(f.section)}</td></tr>" for f in r.lint_findings)
        parts.append(f"<h2>PRD hygiene checks</h2><table><tr><th>ID</th><th>Severity</th><th>Issue</th><th>Where</th></tr>{rows}</table>")
    stats = " · ".join(f"{e(str(k))}: {e(str(v_))}" for k, v_ in r.stats.items())
    parts.append(f"<footer>{e(DISCLAIMER)}<br>{stats}</footer></main><script>{_JS}</script></body></html>")
    return "".join(parts)


def _finding_html(f: ReportFinding) -> str:
    e = html.escape
    verified = {True: "✓ quote verified", False: "⚠ quote not found in PRD", None: "omission"}[f.evidence_verified]
    loc = f" · L{f.line}" if f.line else ""
    quote = f"<blockquote>{e(f.evidence)}</blockquote>" if f.evidence else ""
    mod = f"<p class='meta'><i>Moderator: {e(f.moderator_note)}</i></p>" if f.moderator_note else ""
    return (f"<div class='card finding' data-sev='{f.severity}'><h4><span class='pill {f.severity}'>{f.severity}</span> {f.id} · {e(f.title)}</h4>"
            f"<div class='tags'>{e(', '.join(f.personas))} · {e(f.category)} · {e(f.section)}{loc} · {f.confidence:.0%} · {verified}</div>"
            f"{quote}<p><b>Issue.</b> {e(f.issue)}</p><p><b>What goes wrong.</b> {e(f.failure_scenario)}</p>"
            f"<p><b>Fix.</b> {e(f.recommendation)}</p><p><b>Ask the PM.</b> {e(f.question_for_pm)}</p>{mod}</div>")


def to_json(r: RedTeamReport) -> str:
    return json.dumps(r.model_dump(), indent=2, ensure_ascii=False)
